lines = [l for l in txt.split('\n') if l.startswith('#') and l.endswith(';')]
recs = {}
for l in lines:
    m = re.match(r'(#\d+)=IFC[A-Z0-9_]*\((.*)\);$', l)
    if m:
        idn, body = m.group(1), m.group(2)
        recs[idn] = (l[len(m.group(1))+1:].split('=IFC',1)[1], body)  # keep full
recs[idn] = None
# simpler: split body into fields
def fields(body):
    out=[]; depth=0; cur=''
    for ch in body:
        if ch=='(' : depth+=1; cur+=ch
        elif ch==')': depth-=1; cur+=ch
        elif ch==',' and depth==0: out.append(cur.strip()); cur=''
        else: cur+=ch
    out.append(cur.strip())
    return out
def parse(expr):
    expr = expr.strip()
    if expr.startswith('('):
        return [parse(x) for x in fields(expr)]
    if expr in ('$','$*','$,'): return None
    if expr in ('*','$,'): return None
    if re.match(r'^-?\d+(\.\d+)?([eE]-?\d+)?$', expr): return float(expr)
    if expr.startswith('#'): return ('REF', expr[1:])
    if expr.startswith("'") and expr.endswith("'"): return expr[1:-1]
    if expr in ('.READWRITE.', '.NOCHANGE.'): return expr
    m = re.match(r'^\.(+)\.$', expr)
    if m: return m.group(1)
    return expr
data = {}
for idn, (t, body) in recs.items():
    if t is None: continue
    data[idn] = (t, [parse(f) for f in fields(body)])

