import re

def parse_ifc(path):
    txt = open(path).read()
    lines = [l.strip() for l in txt.split('\n') if re.match(r'^#\d+=IFC', l)]
    ents = {}
    for l in lines:
        m = re.match(r'^(#\d+)=IFC[A-Z0-9_]*\((.*)\);\s*$', l)
        if m:
            ents[m.group(1)] = split_top(m.group(2))
    return ents

def split_top(body):
    out = []; depth = 0; cur = ''; instr = False
    for ch in body:
        if ch == "'":
            instr = not instr; cur += ch; continue
        if instr:
            cur += ch; continue
        if ch == '(':
            depth += 1; cur += ch
        elif ch == ')':
            depth -= 1; cur += ch
        elif ch == ',' and depth == 0:
            out.append(cur.strip()); cur = ''
        else:
            cur += ch
    out.append(cur.strip())
    return out

def val(v, ents):
    """Evaluate an IFC expression to a python value (strings/lists/floats/refs)."""
    if v is None: return None
    s = v.strip()
    if s in ('$', '*'): return None
    if s.startswith('#') and s[1:].lstrip('#').isdigit():
        ref = s
        if ref in ents:
            body = ents[ref]
            # entity: type + args
            t = ref
            return ('ENT', t, body)
        return None
    if s.startswith("'"):
        m = re.match(r"^'(.*)'$", s, re.S)
        return m.group(1) if m else s
    try:
        return float(s)
    except ValueError:
        pass
    if s.startswith('('):
        return [val(x, ents) for x in split_top(s[1:-1]) if x != '$' and x != '']
    m = re.match(r'^\.(.+)\.$', s)
    if m:
        return m.group(1)
    return s

if __name__ == '__main__':
    ents = parse_ifc('project/20_survey/NDDC-A2_Federated_Model_2026.ifc')
    print(len(ents), 'entities')
    walls = [(i, b) for i, b in ents.items() if b and i.startswith('#') and True]
