import numpy as np

ES = 29000.0  # ksi

def q4_k(E_ax, E_ay, G):
    nodes = np.array([[-0.5,-0.5],[0.5,-0.5],[0.5,0.5],[-0.5,0.5]], float)
    K = np.zeros((8,8))
    for xi, wi in [(-0.57735026918962576,0.5),(0.57735026918962576,0.5)]:
        for eta, wj in [(-0.57735026918962576,0.5),(0.57735026918962576,0.5)]:
            Bx = np.zeros(8); By = np.zeros(8); Bg = np.zeros(8)
            for i in range(4):
                n = nodes[i]
                dNdx = n[1]*(1+n[0]*xi)/4.0
                dNdy = n[0]*(1+n[1]*eta)/4.0
                Bx[2*i] = dNdx
                By[2*i+1] = dNdy
                Bg[2*i] = dNdy
                Bg[2*i+1] = dNdx
            D = np.array([E_ax, E_ay, G])
            B = np.vstack([Bx, By, Bg])
            K += wi*wj*(B.T * D) @ B
    return K

