import numpy as np
from diaph import diaph_model, gamma_at, ES
H=5.0
cells=[(i,j) for i in range(20) for j in range(12)]
G=360.0
maps={ (i,j):v for i in range(20) for j in range(12)} 
Ghat_map={(i,j):G for i in range(20) for j in range(12)}
EAx_map={(i,j):2900.0 for i in range(20) for j in range(12)}
EAy_map={(i,j):13920.0 for i in range(20) for j in range(12)}
bars=[]
for i in range(20):
    bars += [((i,0),(i+1,0),3.0,'C'),((i,12),(i+1,12),3.0,'C')]
for j in range(12):
    bars += [((0,j),(0,j+1),3.0,'C'),((20,j),(20,j+1),3.0,'C')]
springs={}
for x in [12.5,37.5,62.5,87.5]:
    c=round(x/H)
    springs.setdefault((c,0),{})['X']=springs.get((c,0),{}).get('X',0.0)+500.0
    springs.setdefault((c,12),{})['X']=springs.get((c,12),{}).get('X',0.0)+500.0
for y in [15,45]:
    r=round(y/H)
    springs.setdefault((0,r),{})['Y']=springs.get((0,r),{}).get('Y',0.0)+500.0
    springs.setdefault((20,r),{})['Y']=springs.get((20,r),{}).get('Y',0.0)+500.0
