        a=m['node_id'][n1]*2; b=m['node_id'][n2]*2
        F[a+1]+=s*w*H/2; F[b+1]+=s*w*H/2
print('net Y load:', F[1::2].sum())
u=np.linalg.solve(m['K'],F)
tot=0.0
for n,sp in springs.items():
    if sp.get('Y'):
        R=sp['Y']*u[m['node_id'][n]*2+1]
